use super::*;
use crate::execution::Registry;
use sqlx::sqlite::{SqlitePoolOptions,SqliteConnectOptions};
struct Fixture{path:std::path::PathBuf,pool:SqlitePool,db:Arc<Db>,binding:Binding,manual:crate::manual_transaction::Registry,registry:Registry}
impl Fixture{
    async fn new()->Self{let path=std::env::temp_dir().join(format!("navkit-table-workflows-{}.sqlite",uuid::Uuid::new_v4()));let options=SqliteConnectOptions::new().filename(&path).create_if_missing(true).foreign_keys(true);let pool=SqlitePoolOptions::new().max_connections(2).connect_with(options).await.unwrap();Self{db:Arc::new(Db::Sqlite(pool.clone())),pool,path,binding:Binding{principal:"fixture-window".into(),owner:"fixture-owner".into(),connection:uuid::Uuid::new_v4().to_string(),namespace:"main".into(),fingerprint:uuid::Uuid::new_v4().to_string()},manual:Default::default(),registry:Default::default()}}
    async fn sql(&self,sql:&str){sqlx::query(sql).execute(&self.pool).await.unwrap();}
    async fn count(&self,table:&str)->i64{sqlx::query_scalar(&format!("SELECT count(*) FROM {}",q(table).unwrap())).fetch_one(&self.pool).await.unwrap()}
    async fn opened(&self,table:&str)->Stored{let ordinary=self.manual.ordinary(&[&self.binding.connection]).await.unwrap();read_owned(self.db.clone(),self.binding.clone(),table.into(),false,ordinary).await.unwrap()}
    fn operation(&self,b:&Stored,kind:&str,target:Option<&str>)->TableWork{TableWork::Operation(TableOperation{connection_id:self.binding.connection.clone(),schema:"main".into(),table:b.public.schema.table.clone(),kind:kind.into(),target_table:target.map(str::to_string),base_revision:b.public.revision.clone(),source_fingerprint:self.binding.fingerprint.clone()})}
    fn entry(&self,work:&TableWork)->Arc<Entry>{let mut r=ExecutionRequest{execution_id:String::new(),connection_id:self.binding.connection.clone(),namespace:"main".into(),owner_id:self.binding.owner.clone(),sql:marker(work).unwrap(),transaction_owner:None,timeout_ms:Some(10000),origin:Some("table-workflow-isolated-test".into()),execution_grant:None,cancel_before_send:false};self.registry.grant_request(&mut r,self.binding.clone()).unwrap();self.registry.register(&r,self.binding.clone(),30).unwrap()}
    async fn execute(&self,work:TableWork)->BoundResult{let e=self.entry(&work);let ordinary=self.manual.ordinary(&[&self.binding.connection]).await.unwrap();run(self.db.clone(),DbKind::of("sqlite"),e,ordinary,work,false).await}
    async fn finish(self){
        drop(self.db);self.pool.close().await;drop(self.pool);
        // Windows：sqlx 物理连接回收可能滞后于 close().await，删除可能短暂失败。
        for _ in 0..50 { match std::fs::remove_file(&self.path) { Ok(()) => return, Err(e) if e.kind()==std::io::ErrorKind::NotFound => return, Err(_) => std::thread::sleep(std::time::Duration::from_millis(20)) } }
        // 最终失败不掩盖真实断言：仅提示残留临时文件。
        eprintln!("table_workflows fixture 临时文件未删除：{:?}", self.path);
    }
}
#[tokio::test]async fn sqlite_copy_full_ddl_data_generated_strict_fk_check_index_trigger_sequence(){
    let f=Fixture::new().await;f.sql("CREATE TABLE audit(value TEXT)").await;f.sql("CREATE TABLE src(id INTEGER PRIMARY KEY AUTOINCREMENT,parent INTEGER REFERENCES src(id),value TEXT COLLATE NOCASE UNIQUE CHECK(length(value)>0),g TEXT GENERATED ALWAYS AS (value||'src') STORED) STRICT").await;f.sql("CREATE INDEX ix_raw ON src(lower(value)) WHERE parent IS NULL").await;f.sql("CREATE TRIGGER tr_raw AFTER INSERT ON src BEGIN INSERT INTO audit(value) VALUES('src'); END").await;f.sql("INSERT INTO src(id,value) VALUES(10,'中文A')").await;f.sql("INSERT INTO src(parent,value) VALUES(10,'B')").await;
    let b=f.opened("src").await;let work=f.operation(&b,"copy_data",Some("copy \" 表"));let r=f.execute(work).await;assert!(r.result.is_ok(),"{:?}",r.result.err());let receipt=r.operation.unwrap();assert!(receipt.verified);assert_eq!(receipt.copied_rows,2);assert_eq!(f.count("audit").await,2);assert_eq!(f.count("src").await,2);
    let c=f.opened("copy \" 表").await;assert!(c.ddl.contains("REFERENCES \"copy \"\" 表\""));assert!(c.ddl.contains("'src'"));assert_eq!(c.public.options.strict,Some(true));assert_eq!(c.sequence,b.sequence);assert_eq!(c.public.schema.foreign_keys[0].ref_table,"copy \" 表");
    f.sql("INSERT INTO \"copy \"\" 表\"(value) VALUES('c')").await;assert_eq!(f.count("audit").await,3);assert_eq!(f.count("src").await,2);assert!(sqlx::query("INSERT INTO \"copy \"\" 表\"(value) VALUES('')").execute(&f.pool).await.is_err());f.finish().await;
}
#[tokio::test]async fn sqlite_empty_copy_keeps_sequence_highwater_and_structure_copy_has_no_data(){let f=Fixture::new().await;f.sql("CREATE TABLE src(id INTEGER PRIMARY KEY AUTOINCREMENT,x TEXT)").await;f.sql("INSERT INTO src(id,x) VALUES(200,'gone')").await;f.sql("DELETE FROM src").await;let b=f.opened("src").await;let r=f.execute(f.operation(&b,"copy_data",Some("dst"))).await;assert!(r.result.is_ok(),"{:?}",r.result.err());assert_eq!(f.opened("dst").await.sequence,Some(200));f.sql("INSERT INTO dst(x) VALUES('new')").await;assert_eq!(sqlx::query_scalar::<_,i64>("SELECT id FROM dst").fetch_one(&f.pool).await.unwrap(),201);let b=f.opened("src").await;let r=f.execute(f.operation(&b,"copy_structure",Some("empty"))).await;assert!(r.result.is_ok(),"{:?}",r.result.err());assert_eq!(f.count("empty").await,0);f.finish().await;}
#[tokio::test]async fn sqlite_clear_preserves_structure_and_existing_target_never_overwritten(){let f=Fixture::new().await;f.sql("CREATE TABLE src(id INTEGER PRIMARY KEY,x TEXT CHECK(length(x)>0)) WITHOUT ROWID").await;f.sql("INSERT INTO src VALUES(1,'A'),(2,'B')").await;f.sql("CREATE TABLE occupied(sentinel TEXT)").await;f.sql("INSERT INTO occupied VALUES('keep')").await;let b=f.opened("src").await;let r=f.execute(f.operation(&b,"copy_structure",Some("occupied"))).await;assert!(r.result.is_err());assert_eq!(f.count("occupied").await,1);let b=f.opened("src").await;let base=b.base.clone();let r=f.execute(f.operation(&b,"clear",None)).await;assert!(r.result.is_ok(),"{:?}",r.result.err());let receipt=r.operation.unwrap();assert!(receipt.verified);assert_eq!(receipt.affected_rows,2);assert_eq!(f.opened("src").await.base,base);assert_eq!(f.count("src").await,0);f.finish().await;}
#[tokio::test]async fn sqlite_stale_schema_generation_owner_and_marker_are_bound(){let f=Fixture::new().await;f.sql("CREATE TABLE src(x TEXT)").await;f.sql("INSERT INTO src VALUES('kept')").await;let b=f.opened("src").await;let mut other=f.binding.clone();other.owner="other-owner".into();let lease=f.manual.ordinary(&[&f.binding.connection]).await.unwrap();let different=read_owned(f.db.clone(),other,"src".into(),false,lease).await.unwrap();assert_ne!(b.public.revision,different.public.revision);assert!(require_baseline(&different,Some(&b.public.revision),Some(&f.binding.fingerprint),&f.binding).is_err());let work=f.operation(&b,"clear",None);let m=marker(&work).unwrap();let mut tampered=match work.clone(){TableWork::Operation(o)=>o,_=>unreachable!()};tampered.kind="copy_data".into();assert_ne!(m,marker(&TableWork::Operation(tampered)).unwrap());f.sql("CREATE TABLE unrelated(x INT)").await;let r=f.execute(work).await;assert!(r.result.is_err());assert_eq!(f.count("src").await,1);f.finish().await;}
#[tokio::test]async fn sqlite_rebuild_preserves_hidden_rowid_raw_dependencies_and_rolls_back_bad_check(){let f=Fixture::new().await;f.sql("CREATE TABLE src(x TEXT,y INTEGER,g TEXT GENERATED ALWAYS AS (x||'literal') STORED)").await;f.sql("CREATE INDEX raw_index ON src(lower(x)) WHERE y>0").await;f.sql("CREATE TABLE audit(x TEXT)").await;f.sql("CREATE TRIGGER raw_trigger AFTER INSERT ON src BEGIN INSERT INTO audit VALUES(NEW.x); END").await;f.sql("CREATE VIEW kept_view AS SELECT x FROM src").await;f.sql("INSERT INTO src(rowid,x,y) VALUES(42,'A',1),(90,'中文',2)").await;let b=f.opened("src").await;let ddl=b.ddl.clone();let mut d=b.public.design.clone();d.checks=Some(vec![CheckDesign{name:"positive".into(),orig_name:None,expression:"y>100".into(),generated_name:false}]);let r=f.execute(TableWork::Design(d)).await;assert!(r.result.is_err());assert_eq!(f.opened("src").await.ddl,ddl);assert_eq!(f.count("src").await,2);
    let b=f.opened("src").await;let indexes=b.indexes.clone();let mut d=b.public.design.clone();d.checks=Some(vec![CheckDesign{name:"positive".into(),orig_name:None,expression:"y>0".into(),generated_name:false}]);let r=f.execute(TableWork::Design(d)).await;assert!(r.result.is_ok(),"{:?}",r.result.err());assert!(r.design.unwrap().receipt.verified);let after=f.opened("src").await;assert_eq!(after.indexes,indexes);let rowids:Vec<i64>=sqlx::query_scalar("SELECT rowid FROM src ORDER BY rowid").fetch_all(&f.pool).await.unwrap();assert_eq!(rowids,vec![42,90]);assert_eq!(f.count("kept_view").await,2);assert_eq!(f.count("audit").await,2);assert!(sqlx::query("INSERT INTO src(x,y) VALUES('bad',0)").execute(&f.pool).await.is_err());f.finish().await;
}
#[tokio::test]async fn sqlite_checks_triggers_undefined_preserve_empty_clears_and_engine_comment_reject(){let f=Fixture::new().await;f.sql("CREATE TABLE src(id INTEGER PRIMARY KEY,x TEXT CHECK(x<>'bad'))").await;f.sql("CREATE TABLE audit(x TEXT)").await;f.sql("CREATE TRIGGER old AFTER INSERT ON src BEGIN INSERT INTO audit VALUES(NEW.x); END").await;let b=f.opened("src").await;let mut d=b.public.design.clone();d.checks=None;d.triggers=None;let r=f.execute(TableWork::Design(d)).await;assert!(r.result.is_ok(),"{:?}",r.result.err());let b=f.opened("src").await;assert_eq!(b.public.objects.checks.len(),1);assert_eq!(b.public.objects.triggers.len(),1);let mut d=b.public.design.clone();d.checks=Some(vec![]);d.triggers=Some(vec![]);let r=f.execute(TableWork::Design(d)).await;assert!(r.result.is_ok(),"{:?}",r.result.err());f.sql("INSERT INTO src(x) VALUES('bad')").await;assert_eq!(f.count("audit").await,0);let b=f.opened("src").await;let mut d=b.public.design.clone();d.options=Some(TableOptionsDesign{engine:Some("InnoDB".into()),..Default::default()});assert!(design_steps(&b,&d).is_err());d.options=None;d.comment=Some("fake comment".into());assert!(design_steps(&b,&d).is_err());f.finish().await;}
#[tokio::test]async fn sqlite_partial_metadata_and_generated_column_edit_refuse_without_changes(){let f=Fixture::new().await;f.sql("CREATE TABLE src(x TEXT,g TEXT GENERATED ALWAYS AS (x||'src') STORED)").await;let b=f.opened("src").await;let mut d=b.public.design.clone();d.columns[1].data_type="INTEGER".into();assert!(design_steps(&b,&d).is_err());let mut conn=f.pool.acquire().await.unwrap();sqlx::query("PRAGMA writable_schema=ON").execute(&mut *conn).await.unwrap();sqlx::query("UPDATE sqlite_schema SET sql='CREATE TABLE src(' WHERE name='src'").execute(&mut *conn).await.unwrap();sqlx::query("PRAGMA writable_schema=OFF").execute(&mut *conn).await.unwrap();let bad=snapshot(&mut conn,&f.pool,&f.binding,"src",false).await;assert!(bad.is_err());conn.return_to_pool().await;f.finish().await;}
#[tokio::test]async fn sqlite_stop_before_send_is_confirmed_without_any_ddl(){let f=Fixture::new().await;f.sql("CREATE TABLE src(x TEXT)").await;f.sql("INSERT INTO src VALUES('kept')").await;let b=f.opened("src").await;let work=f.operation(&b,"clear",None);let e=f.entry(&work);e.request_stop(false);let lease=f.manual.ordinary(&[&f.binding.connection]).await.unwrap();let r=run(f.db.clone(),DbKind::of("sqlite"),e,lease,work,false).await;assert!(r.result.is_err());assert!(r.confirmed);assert_eq!(f.count("src").await,1);f.finish().await;}
#[tokio::test]async fn sqlite_new_index_trigger_and_check_save_have_real_database_effects(){
    let f=Fixture::new().await;f.sql("CREATE TABLE src(id INTEGER PRIMARY KEY,x TEXT)").await;f.sql("CREATE TABLE audit(x TEXT)").await;
    let b=f.opened("src").await;let mut d=b.public.design.clone();d.indexes=Some(vec![IndexDesign{name:"saved_index".into(),columns:vec!["x".into()],unique:true,..Default::default()}]);d.triggers=Some(vec![TriggerDesign{name:"saved_trigger".into(),orig_name:None,timing:"AFTER".into(),event:"INSERT".into(),statement:"INSERT INTO audit(x) VALUES(NEW.x)".into(),definition:None}]);
    let r=f.execute(TableWork::Design(d)).await;assert!(r.result.is_ok(),"{:?}",r.result.err());assert!(r.design.unwrap().receipt.verified);f.sql("INSERT INTO src VALUES(1,'saved')").await;assert_eq!(f.count("audit").await,1);assert!(sqlx::query("INSERT INTO src VALUES(2,'saved')").execute(&f.pool).await.is_err());
    let b=f.opened("src").await;assert!(b.public.schema.indexes.iter().any(|i|i.name=="saved_index"&&i.unique));let mut d=b.public.design.clone();d.indexes=None;d.triggers=None;d.checks=Some(vec![CheckDesign{name:"saved_check".into(),orig_name:None,expression:"id>0".into(),generated_name:false}]);let r=f.execute(TableWork::Design(d)).await;assert!(r.result.is_ok(),"{:?}",r.result.err());assert!(r.design.unwrap().receipt.verified);assert!(sqlx::query("INSERT INTO src VALUES(-1,'blocked')").execute(&f.pool).await.is_err());f.sql("INSERT INTO src VALUES(3,'preserved trigger')").await;assert_eq!(f.count("audit").await,2);f.finish().await;
}
#[tokio::test]async fn sqlite_unknown_keeps_actual_resource_quarantined_until_drain(){let f=Fixture::new().await;f.sql("CREATE TABLE src(x TEXT)").await;let b=f.opened("src").await;let work=f.operation(&b,"clear",None);let e=f.entry(&work);assert!(e.start());let (tx,rx)=tokio::sync::oneshot::channel::<()>();let mut conn=f.pool.acquire().await.unwrap();sqlx::query("BEGIN IMMEDIATE").execute(&mut *conn).await.unwrap();sqlx::query("INSERT INTO src VALUES('pending')").execute(&mut *conn).await.unwrap();e.request_stop(false);let (r,proof)=execution::supervise_with_grace(e.clone(),async move{let _=rx.await;sqlx::query("ROLLBACK").execute(&mut *conn).await.unwrap();conn.return_to_pool().await;(Err(AppError::coded("TABLE_STOPPED_ROLLED_BACK","真实事务已回滚")),true)},std::time::Duration::from_millis(1)).await;assert!(!proof);assert_eq!(r.unwrap_err().code,"EXECUTION_EFFECTS_UNKNOWN");assert!(e.status().resources_pending);assert!(f.registry.require_quiescent(&f.binding.connection).is_err());tx.send(()).unwrap();tokio::time::timeout(std::time::Duration::from_secs(2),async{while e.status().resources_pending{tokio::task::yield_now().await;}}).await.unwrap();assert_eq!(f.count("src").await,0);f.finish().await;}
